import { useState } from "react";
import { asChat, prettyValue } from "@/lib/trace/chat";
import type { ChatMessage } from "@/lib/trace/types";
import { Button } from "@/components/ui/button";
import { JsonViewer } from "@/components/ui/json-viewer";
import { MessageItem, type RenderMarkdown } from "@/components/ui/message-card";

const REDACTED = "<REDACTED>";
// Above this many messages a history collapses to first + last N behind a "Show N more" toggle.
const COLLAPSE_THRESHOLD = 8;
const HEAD_TAIL = 3;

export interface IOCardsProps {
  /** Raw payload string: a chat-message-array JSON, other JSON, or plain text. */
  value?: string;
  /** Optional slot for rendering markdown bodies (e.g. react-markdown + sanitize). Default: plain text. */
  renderMarkdown?: RenderMarkdown;
  "data-testid"?: string;
}

/**
 * IOCards — renders a span's input/output value. A chat-message array becomes
 * role-labeled cards (with tool-call/result linkage and long-history
 * collapse); a redacted marker and non-chat payloads fall back to a plain
 * message or the dependency-free `JsonViewer`. Markdown bodies go through the
 * optional `renderMarkdown` slot — the default renderer NEVER interprets HTML
 * (XSS-safe by construction; no `dangerouslySetInnerHTML` anywhere).
 */
export function IOCards({ value, renderMarkdown, "data-testid": testId }: IOCardsProps) {
  if (value === undefined || value === null || value === "") {
    return <p className="text-muted-foreground text-xs">—</p>;
  }
  if (value === REDACTED) {
    return (
      <p className="text-muted-foreground text-xs" data-testid={testId}>
        Redacted by the client (prompt logging is off).
      </p>
    );
  }
  const chat = asChat(value);
  if (chat) {
    return (
      <div data-slot="io-cards" data-testid={testId}>
        <MessageFeed messages={chat} renderMarkdown={renderMarkdown} />
      </div>
    );
  }
  // Non-chat payload → the JsonViewer fallback (dependency-free, ADR D3).
  return <NonChatFallback value={value} testId={testId} />;
}

function NonChatFallback({ value, testId }: { value: string; testId?: string }) {
  try {
    return <JsonViewer value={JSON.parse(value)} collapsed={1} enableCopy />;
  } catch {
    return (
      <pre data-testid={testId} className="overflow-auto rounded-md border p-2 font-mono text-xs">
        {prettyValue(value)}
      </pre>
    );
  }
}

function MessageFeed({
  messages,
  renderMarkdown,
}: {
  messages: ChatMessage[];
  renderMarkdown?: RenderMarkdown;
}) {
  const [expanded, setExpanded] = useState(false);
  const collapsible = messages.length > COLLAPSE_THRESHOLD;

  if (!collapsible || expanded) {
    return (
      <div className="space-y-2">
        {messages.map((m, i) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: chat messages carry no stable id; the transcript is append-only so index is the natural key
          <MessageItem key={i} message={m} renderMarkdown={renderMarkdown} />
        ))}
        {collapsible && expanded ? (
          <Button variant="ghost" size="sm" onClick={() => setExpanded(false)}>
            Show less
          </Button>
        ) : null}
      </div>
    );
  }

  const head = messages.slice(0, HEAD_TAIL);
  const tail = messages.slice(messages.length - HEAD_TAIL);
  const hiddenCount = messages.length - head.length - tail.length;

  return (
    <div className="space-y-2">
      {head.map((m, i) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: chat messages carry no stable id (append-only feed)
        <MessageItem key={`h-${i}`} message={m} renderMarkdown={renderMarkdown} />
      ))}
      <Button variant="ghost" size="sm" onClick={() => setExpanded(true)}>
        {`Show ${hiddenCount} more`}
      </Button>
      {tail.map((m, i) => (
        // biome-ignore lint/suspicious/noArrayIndexKey: chat messages carry no stable id (append-only feed)
        <MessageItem key={`t-${i}`} message={m} renderMarkdown={renderMarkdown} />
      ))}
    </div>
  );
}

import type { ReactNode } from "react";
import { useState } from "react";
import { contentText, isRedactedThinking, prettyValue } from "@/lib/trace/chat";
import type { ChatMessage, ToolCall } from "@/lib/trace/types";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { CopyButton } from "@/components/ui/copy-button";
import { JsonViewer } from "@/components/ui/json-viewer";

/** Chat role → Badge variant (visual triage, not bubbles). */
function roleVariant(role: string): "default" | "primary" | "accent" | "outline" {
  if (role === "user") return "primary";
  if (role === "assistant") return "accent";
  if (role === "system") return "default";
  return "outline";
}

export type RenderMarkdown = (text: string) => ReactNode;

/** Props shared by the message-rendering components (kills the repeated `{message, renderMarkdown}` shape). */
interface MessageProps {
  message: ChatMessage;
  renderMarkdown?: RenderMarkdown;
}

/** Default body renderer — plain text with preserved whitespace. NEVER interprets HTML (XSS-safe). */
function PlainText({ text }: { text: string }) {
  return <p className="whitespace-pre-wrap break-words text-body-sm">{text}</p>;
}

/** A bordered, role-labeled Card: role Badge + body (markdown slot or plain text) + raw-JSON toggle. */
export function MessageCard({ message, renderMarkdown }: MessageProps) {
  const [showRaw, setShowRaw] = useState(false);
  const redacted = isRedactedThinking(message);
  const body = contentText(message.content);

  return (
    <Card size="sm" data-slot="io-card" data-testid="io-card">
      <Card.Body className="space-y-2">
        <div className="flex items-center gap-2">
          <Badge variant={roleVariant(message.role)}>{message.role}</Badge>
          <div className="ml-auto flex items-center gap-1">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              aria-label={showRaw ? "Hide raw JSON" : "Show raw JSON"}
              onClick={() => setShowRaw((r) => !r)}
            >
              {showRaw ? "Hide JSON" : "Raw JSON"}
            </Button>
            <CopyButton
              value={JSON.stringify(message)}
              aria-label="Copy message JSON"
              variant="ghost"
              size="sm"
            />
          </div>
        </div>
        {redacted ? (
          <p className="text-muted-foreground text-xs italic">[Redacted thinking]</p>
        ) : body ? (
          renderMarkdown ? (
            renderMarkdown(body)
          ) : (
            <PlainText text={body} />
          )
        ) : (
          <p className="text-muted-foreground text-xs">—</p>
        )}
        {showRaw ? <JsonViewer value={message} collapsed={1} enableCopy /> : null}
      </Card.Body>
    </Card>
  );
}

/** A dedicated tool-call card: function name + call-id + JSON arguments. Linked to its result by id. */
export function ToolCallCard({ call }: { call: ToolCall }) {
  const name = call.function?.name ?? "(unnamed tool)";
  const args = call.function?.arguments ?? "";
  return (
    <Card size="sm" data-slot="io-tool-call">
      <Card.Body className="space-y-2">
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="outline">tool call</Badge>
          <span className="font-mono font-semibold text-xs">{name}</span>
          <span className="font-mono text-[10px] text-muted-foreground">{call.id}</span>
          <div className="ml-auto">
            <CopyButton value={args} aria-label="Copy tool arguments" variant="ghost" size="sm" />
          </div>
        </div>
        {args ? <JsonViewerText text={prettyValue(args)} /> : null}
      </Card.Body>
    </Card>
  );
}

/** A tool-result card, linked to its originating call by `tool_call_id`. */
export function ToolResultCard({ message }: { message: ChatMessage }) {
  const id = message.tool_call_id ?? "";
  const text = contentText(message.content);
  return (
    <Card size="sm" data-slot="io-tool-result">
      <Card.Body className="space-y-2">
        <div className="flex flex-wrap items-center gap-2">
          <Badge variant="outline">tool result</Badge>
          <span className="font-mono text-[10px] text-muted-foreground">↳ {id}</span>
          <div className="ml-auto">
            <CopyButton value={text} aria-label="Copy tool result" variant="ghost" size="sm" />
          </div>
        </div>
        <JsonViewerText text={prettyValue(text)} />
      </Card.Body>
    </Card>
  );
}

/** Parse a pretty-printed string back to a value for the JsonViewer; falls back to a plain text node. */
function JsonViewerText({ text }: { text: string }) {
  try {
    return <JsonViewer value={JSON.parse(text)} collapsed={1} enableCopy />;
  } catch {
    return <pre className="overflow-auto rounded-md border p-2 font-mono text-xs">{text}</pre>;
  }
}

/** Render one chat message as its appropriate card kind (tool-result → tool-calls → plain message). */
export function MessageItem({ message, renderMarkdown }: MessageProps) {
  if (message.role === "tool" && message.tool_call_id) {
    return <ToolResultCard message={message} />;
  }
  const calls = message.tool_calls ?? [];
  if (calls.length > 0) {
    const hasBody = contentText(message.content) !== "" || isRedactedThinking(message);
    return (
      <div className="space-y-2">
        {hasBody ? <MessageCard message={message} renderMarkdown={renderMarkdown} /> : null}
        {calls.map((c) => (
          <ToolCallCard key={c.id} call={c} />
        ))}
      </div>
    );
  }
  return <MessageCard message={message} renderMarkdown={renderMarkdown} />;
}
